"""Persistent original routing-only QR; synthetic pixels, no bank details or real payments."""
import base64,hashlib,json,secrets,subprocess,requests
import test_automatic_paid_access as access
PNG=base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=')
class ManualQr(access.AutomaticPaidAccess):
 @classmethod
 def setUpClass(cls):
  super().setUpClass()
  for op in ['support','publication','maxapp','qr']:
   r=subprocess.run([cls.f.php,str(cls.f.path/('scripts/migrate-'+op+'.php')),'up'],capture_output=True,text=True)
   if r.returncode:raise RuntimeError(r.stderr)
 def setUp(self):
  for t in ['nd_manual_qr_assignments','nd_manual_qr_settings','nd_manual_qr_versions']:self.f.sql('DELETE FROM '+t)
  super().setUp()
 def qa(self,r,d=None,s=None,mode='owner',invoice=None):
  s=s or self.owner;u=self.base+'/payment-api.php?mode='+mode+'&r='+r+(('&invoice='+str(invoice)) if invoice else '')
  if d is None:return s.get(u)
  d.setdefault('request_key',secrets.token_hex(32));return s.post(u,json=d)
 def upload(self):
  settings=self.qa('settings').json()['settings'];r=self.owner.post(self.base+'/payment-api.php?mode=owner&r=upload',data={'version':settings['version'],'recipient_name':'SYNTHETIC recipient'},files={'file':('SYNTHETIC-original.png',PNG,'image/png')});self.assertEqual(r.status_code,200,r.text);return r.json()['settings']
 def enable(self,s=None):
  s=s or self.qa('settings').json()['settings'];r=self.qa('toggle',{'version':int(s['version']),'enabled':True,'confirm':True,'recipient_confirmed':True,'recipient_name':s['qr']['recipient_name'],'checksum':s['qr']['checksum']});self.assertEqual(r.status_code,200,r.text);return r.json()['settings']
 def guest(self,oid,docs):
  link=self.create_link(oid,docs,False);self.assertEqual(link.status_code,200,link.text);g,x=self.exchange(link.json()['url'].split('#token=')[1]);self.consent(g,x);return g
 def test_original_settings_auth_replacement_disables_and_prevents_public_access(self):
  self.assertEqual(requests.get(self.base+'/payment-api.php?mode=owner&r=settings').status_code,401);s=self.upload();self.assertFalse(s['enabled']);self.assertEqual(self.qa('preview').content,PNG);self.assertEqual(s['qr']['checksum'],hashlib.sha256(PNG).hexdigest());self.assertEqual(self.qa('toggle',{'version':int(s['version']),'enabled':True,'confirm':True,'recipient_confirmed':False}).status_code,422);s=self.enable(s);self.assertTrue(s['enabled']);new=self.upload();self.assertFalse(new['enabled']);self.assertNotEqual(new['qr']['id'],s['qr']['id']);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_manual_qr_versions')[0]['n'],2);r=self.owner.post(self.base+'/payment-api.php?mode=owner&r=upload',data={'version':new['version'],'recipient_name':'SYNTHETIC'},files={'file':('bad.svg',b'<svg/>','image/svg+xml')});self.assertEqual(r.status_code,422)
 def test_scoped_original_download_release_gate_pending_claim_and_existing_bank_invitation(self):
  self.enable(self.upload());oid,items,docs=self.prepared();i=items[0];iid=int(i['id']);g=self.guest(oid,docs);r=self.qa('status',s=g,mode='prospect',invoice=iid);self.assertEqual(r.status_code,200,r.text);d=r.json();self.assertEqual(d['outstanding'],str(i['total_minor']//100)+'.00' if int(i['total_minor'])%100==0 else d['outstanding']);self.assertTrue(d['qr']);self.assertEqual(d['order_reference'],i['snapshot']['order']['number']);self.assertEqual(self.qa('image',s=g,mode='prospect',invoice=iid).content,PNG);download=self.qa('image&download=1',s=g,mode='prospect',invoice=iid);self.assertEqual(download.content,PNG);self.assertIn('attachment',download.headers['Content-Disposition']);self.assertNotEqual(self.qa('image',s=requests.Session(),mode='prospect',invoice=iid).status_code,200);self.assertNotEqual(self.qa('image',s=self.stranger,mode='customer',invoice=iid).status_code,200)
  self.f.sql('UPDATE nd_lc_pdf_assets SET payment_released_at=NULL WHERE binding_id=?',params=[docs[0]['id']]);self.assertEqual(self.qa('image',s=g,mode='prospect',invoice=iid).status_code,404);self.f.sql('UPDATE nd_lc_pdf_assets SET payment_released_at=UTC_TIMESTAMP() WHERE binding_id=?',params=[docs[0]['id']]);claim={'amount':'10.00','paid_at':'2026-01-10 12:00:00','payer':'SYNTHETIC payer','reference':'SYNTHETIC pending only'};self.assertEqual(self.qa('claim',claim.copy(),s=g,mode='prospect',invoice=iid).status_code,403);g.headers['X-Neuro-Payment-CSRF']=d['csrf'];r=self.qa('claim',claim,s=g,mode='prospect',invoice=iid);self.assertEqual(r.status_code,200,r.text);self.assertFalse(r.json()['client_access_activated']);self.assertEqual(self.smtp.messages,[]);self.assertEqual(self.qa('claim',claim,s=g,mode='prospect',invoice=iid).status_code,200);self.assertEqual(self.f.sql("SELECT COUNT(*) n FROM nd_lc_prospect_events WHERE action='payment_claimed' AND JSON_UNQUOTE(JSON_EXTRACT(evidence_json,'$.invoice_id'))=?",params=[str(iid)])[0]['n'],1)
  self.assertTrue(self.qa('claims').json()['items']);self.assertEqual(self.qa('review-claim',{'event_id':int(next(x for x in self.qa('claims').json()['items'] if x['invoice_id']==iid)['event_id']),'payment_id':999999,'confirm':True,'reason':'SYNTHETIC not a bank record'}).status_code,409);self.assertEqual(self.bank(i).status_code,200);pending=next(x for x in self.qa('claims').json()['items'] if x['invoice_id']==iid);self.assertEqual(self.qa('review-claim',{'event_id':pending['event_id'],'payment_id':int(pending['payments'][0]['id']),'confirm':True,'reason':'SYNTHETIC linked to existing verified fixture record'}).status_code,200);self.assertNotIn(pending['event_id'],[x['event_id'] for x in self.qa('claims').json()['items']]);self.assertEqual(len(self.smtp.messages),1);self.assertFalse(self.job(oid)['delivery_confirmed']);self.assertEqual(self.qa('image',s=g,mode='prospect',invoice=iid).status_code,404);self.assertEqual(self.qa('status',s=g,mode='prospect',invoice=iid).json()['outstanding'],'0.00');self.assertEqual(self.f.sql("SELECT COUNT(*) n FROM nd_lc_receipt_tasks WHERE state='MISSING'")[0]['n'],1)
 def test_browser_owner_upload_and_scoped_phone_payment_pending_only(self):
  import os
  from playwright.sync_api import sync_playwright,expect
  oid,items,docs=self.prepared();iid=int(items[0]['id']);g=self.guest(oid,docs)
  with sync_playwright() as pw:
   b=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);context=b.new_context(viewport={'width':375,'height':812});p=context.new_page();p.goto(self.base+'/studio.php');p.locator('#password').fill(self.f.password);p.locator('#login-form button').click();p.locator('#dashboard').wait_for(state='visible');p.goto(self.base+'/payment-settings.php');p.get_by_label('Название получателя',exact=True).fill('SYNTHETIC recipient');p.get_by_label('Загрузить / заменить исходное изображение QR',exact=True).set_input_files({'name':'SYNTHETIC.png','mimeType':'image/png','buffer':PNG});p.get_by_role('button',name='Сохранить оригинал приватно',exact=True).click();p.get_by_label('Я проверил получателя для этого оригинала и подтверждаю изменение',exact=True).check();p.get_by_role('button',name='Проверить и включить QR',exact=True).click();p.locator('#qr-settings article').filter(has_text=items[0]['number']).get_by_role('button',name='Выдать текущий QR этому заказу',exact=True).click();p.get_by_text('Текущий QR уже выдан.',exact=True).first.wait_for();
   if os.environ.get('NEURO_GUIDE_SHOTS'):p.set_viewport_size({'width':1000,'height':850});p.evaluate('window.scrollTo(0,0)');p.screenshot(path=str(__import__('pathlib').Path(os.environ['NEURO_GUIDE_SHOTS'])/'payment-settings.png'),full_page=False)
   guest=b.new_context(viewport={'width':375,'height':812});guest.add_cookies([{'name':c.name,'value':c.value,'url':self.base} for c in g.cookies]);phone=guest.new_page();phone.goto(self.base+'/payment.php?mode=prospect&invoice='+str(iid));phone.get_by_role('link',name='Скачать изображение QR для оплаты с этого телефона',exact=True).wait_for();phone.get_by_label('Время перевода по Калининграду',exact=True).fill('2026-01-10T12:00');phone.get_by_label('Плательщик',exact=True).fill('SYNTHETIC browser payer');phone.get_by_label('Назначение / номер перевода',exact=True).fill('SYNTHETIC browser claim only');phone.get_by_role('button',name='Я оплатил — отправить на сверку',exact=True).click();expect(phone.locator('#payment-message')).to_contain_text('Сообщение сохранено.',timeout=10000);self.assertFalse(phone.evaluate('document.documentElement.scrollWidth>innerWidth'));self.assertEqual(self.smtp.messages,[]);self.assertFalse(self.f.sql('SELECT id FROM nd_payment_transactions'));b.close()
for name in dir(access.AutomaticPaidAccess):
 if name.startswith('test_'):setattr(ManualQr,name,None)
